import requests
from bs4 import BeautifulSoup
import pandas as pd
from io import StringIO
def task_func(url, table_id):
    response = requests.get(url, verify=False)
    response.raise_for_status()

    soup = BeautifulSoup(response.text, 'html.parser')
    table = soup.find('table', id=table_id)

    if table is None:
        raise ValueError("Table with the specified ID not found.")

    rows = table.find_all('tr')

    if not rows:
        return pd.DataFrame()

    data = []
    for row in rows:
        cells = row.find_all(['td', 'th'])
        if not cells:
            continue
        row_data = [cell.get_text(strip=True) for cell in cells]
        data.append(row_data)

    if not data:
        return pd.DataFrame()

    df = pd.DataFrame(data)
    return df

import requests
from bs4 import BeautifulSoup
import pandas as pd
from io import StringIO
def task_func(url, table_id):
    response = requests.get(url, verify=False)
    response.raise_for_status()

    soup = BeautifulSoup(response.text, 'html.parser')
    table = soup.find('table', id=table_id)

    if table is None:
        raise ValueError("Table with the specified ID not found.")

    rows = table.find_all('tr')

    if not rows:
        return pd.DataFrame()

    headers = []
    data = []

    first_row = True
    for row in rows:
        th_elements = row.find_all('th')
        td_elements = row.find_all('td')

        if th_elements and first_row:
            headers = [th.get_text(strip=True) for th in th_elements]
            first_row = False
        elif td_elements:
            if not headers:
                headers = [f"Column_{i}" for i in range(len(td_elements))]
            data.append([td.get_text(strip=True) for td in td_elements])
        elif th_elements and not headers:
            headers = [th.get_text(strip=True) for th in th_elements]
            first_row = False

    if not data:
        return pd.DataFrame()

    df = pd.DataFrame(data, columns=headers)
    return df

