import requests
from lxml import html
import pandas as pd
import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    try:
        response = requests.get(webpage_url, verify=False)
        response.raise_for_status()
    except requests.RequestException as e:
        raise requests.RequestException(f"Network issue accessing URL: {e}")

    try:
        tree = html.fromstring(response.content)
        tables = pd.read_html(tree)
    except Exception as e:
        raise ValueError(f"Error parsing HTML table: {e}")

    if not tables:
        return 0

    df = tables[0]
    num_rows = len(df)

    if num_rows == 0:
        return 0

    try:
        conn = sqlite3.connect(database_name)
        df.to_sql("my_table", conn, if_exists="replace", index=False)
        conn.commit()
        conn.close()
    except sqlite3.DatabaseError as e:
        raise sqlite3.DatabaseError(f"Database error: {e}")

    return num_rows

import requests
from lxml import html
import pandas as pd
import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    try:
        response = requests.get(webpage_url, verify=False)
        response.raise_for_status()
        html_content = response.text
    except requests.RequestException as e:
        raise requests.RequestException(f"Network issue accessing URL: {e}")

    try:
        tree = html.fromstring(html_content)
        tables = tree.xpath('//table')

        if not tables:
            return 0

        df = pd.read_html(html_content)[0]

        if df.empty:
            return 0

        row_count = len(df)

        conn = sqlite3.connect(database_name)
        try:
            df.to_sql('my_table', conn, if_exists='replace', index=False)
        finally:
            conn.close()

        return row_count

    except sqlite3.DatabaseError as e:
        raise sqlite3.DatabaseError(f"Database error: {e}")
    except Exception:
        return 0

