import pandas as pd
import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    if webpage_url.startswith(('http://', 'https://')):
        try:
            response = requests.get(webpage_url, verify=False)
            response.raise_for_status()
            html_content = response.text
        except requests.RequestException as e:
            raise requests.RequestException(f"Network issue accessing URL: {e}")
    else:
        try:
            with open(webpage_url, 'r', encoding='utf-8') as f:
                html_content = f.read()
        except FileNotFoundError:
            raise requests.RequestException(f"Local file not found: {webpage_url}")
        except IOError as e:
            raise requests.RequestException(f"Error reading local file: {e}")

    try:
        tree = html.fromstring(html_content)
        tables = pd.read_html(tree)

        if not tables:
            return 0

        df = tables[0]

        if df.empty:
            return 0

        conn = sqlite3.connect(database_name)
        try:
