import requests
import logging
def task_func(repo_url: str) -> dict:
    if not isinstance(repo_url, str) or not repo_url:
        raise ValueError("Repository URL must be a non-empty string.")

    try:
        response = requests.get(repo_url, timeout=10, verify=False)
        response.raise_for_status()
        data = response.json()
    except requests.HTTPError as e:
        raise requests.exceptions.HTTPError(f"HTTP error occurred while fetching {repo_url}: {e}")
    except requests.RequestException as e:
        raise requests.exceptions.RequestException(f"Request failed for {repo_url}: {e}")

    open_issues = data.get('open_issues_count', 0)
    if open_issues > 100:
        logging.warning(f"The repository has a large number of open issues: {open_issues}")

    return data

